from bisect import bisect_right

class CurriculumSchedule(): 
    "Manage curriculum learning for shifts in pitch and time."
    def __init__(self, cfg, intervals=None): 
        self.cfg = cfg
        self.max_shifts_x = list(range(cfg.training.init_shift_x, cfg.training.max_shift_x+1))
        self.max_shifts_y = list(range(cfg.training.init_shift_y, cfg.training.max_shift_y+1))
        if intervals is None: self.intervals = [100, 25, 40, 40, 40, 25, 40, 40, 40, 20, 20, 20]
        elif not isinstance(intervals, (tuple, list)): self.intervals = [intervals]*12 # :shrug: 
        else: self.intervals = intervals
        self.epoch_bounds = []        
        _t = 1 # my epochs start at 1 not zero. shouldn't matter but so it is. 
        for n in self.intervals:
            _t += n; self.epoch_bounds.append(_t)
        self.prev_stage = -1  # for lr schedling 

    def __call__(self, shared_ct_dict, epoch, verbose=False):

        training = shared_ct_dict['training']
        idx = min(bisect_right(self.epoch_bounds, epoch), len(self.max_shifts_x)-1) # which interval we're in; clamp at last
        training['max_shift_x'], training['max_shift_y']  = self.max_shifts_x[idx], self.max_shifts_y[idx]
        if verbose: print(f"curr_learn: max_shift_x = {training['max_shift_x']}, max_shift_y = {training['max_shift_y']}")
        return training

    def step(self, epoch, optimizer):
        stage_idx = min(bisect_right(self.epoch_bounds, epoch), len(self.intervals)-1)
        if stage_idx != self.prev_stage:
            self.scheduler = OneCycleLR(optimizer, max_lr=self.cfg.training.lr,
                                   steps_per_epoch=1, epochs=self.intervals[stage_idx], div_factor=5)
            self.prev_stage = stage_idx
        else:
            self.scheduler.step()

