#@torch.compiler.disable
def compute_batch_loss(batch, encoder, cfg, global_step, mae_decoder=None, ema_encoder=None, debug=False):
    "Compute loss and return other exal auxiliary variables (for train or val)"
    device = next(encoder.parameters()).device
    img1, img2, deltas = batch['img1'].to(device, non_blocking=True), batch['img2'].to(device, non_blocking=True), batch['deltas'].to(device, non_blocking=True)

    enc1_fn  = ema_encoder if ema_encoder is not None else encoder
    enc_out1 = enc1_fn(img1, mask_ratio=cfg.training.mask_ratio)
    enc_out2 = encoder(img2, mae_mask=enc_out1.mae_mask)

    loss_dict = {}
    recon_patches = None
    if mae_decoder is not None: # recon at finest scale
        eo = enc_out2.patches[-1] # readibility/convenience variable
        recon_patches = mae_decoder(enc_out2) 
        if debug:
            for i, lv in enumerate(enc_out2.patches.levels):
                print(f"level {i}: {lv.emb.isnan().any()}, min={lv.emb.min():.4f}, max={lv.emb.max():.4f}")
        loss_dict['mae'] = calc_mae_loss(recon_patches, img2, enc_out2, lambda_visible=cfg.training.get('lambda_visible',0.1)) # created here. 

    if isinstance(enc_out1.patches, HierarchicalPatchState):
        z1 = [lvl.emb for lvl in enc_out1.patches.levels]
        z2 = [lvl.emb for lvl in enc_out2.patches.levels]
        non_emptys = [(l1.non_empty, l2.non_empty) for l1, l2 in zip(enc_out1.patches.levels, enc_out2.patches.levels)]
    else:
        z1 = enc_out1.patches.all_emb.reshape(-1, enc_out1.patches[1].dim)
        z2 = enc_out2.patches.all_emb.reshape(-1, enc_out2.patches[1].dim)
        non_emptys = (enc_out1.patches.all_non_empty, enc_out2.patches.all_non_empty)

    loss_dict = loss_dict | calc_enc_loss_multiscale(z1, z2, global_step, img_size=cfg.data.image_size, deltas=deltas, 
                lambd=cfg.training.lambd, non_emptys=non_emptys, lambda_anchor=cfg.training.get('lambda_anchor',0.05))

    if 'mae' in loss_dict.keys(): loss_dict['loss'] += cfg.training.get('lambda_mae', 1.0) * loss_dict['mae']
    if torch.isnan(loss_dict['loss']):
        cjprint("*** NaN detected! ***", {k: v.item() if hasattr(v, 'item') else v for k, v in loss_dict.items()}, color="red")
        breakpoint()
    return loss_dict, (z1, z2), (enc_out1, enc_out2), recon_patches

# %% ../nbs/06_train_enc.ipynb #69be248f-4310-4da7-81f2-826063804f8d
@hydra.main(version_base=None, config_path="../configs", config_name="config")
def train(cfg: DictConfig):
    device = 'cuda' if torch.cuda.is_available() else 'mps' if torch.backends.mps.is_available() else 'cpu'
    cjprint(f"config file: {HydraConfig.get().job.config_name}\nconfig: {cfg}\ndevice = {device}",color="green")
    set_seed()

    manager = mp.Manager()
    shared_ct_dict = manager.dict(OmegaConf.to_container(cfg))
    
    train_ds = PRPairDataset(image_dataset_dir=cfg.data.path, split='train', max_shift_x=cfg.training.max_shift_x, max_shift_y=cfg.training.max_shift_y, shared=shared_ct_dict) 
    val_ds   = PRPairDataset(image_dataset_dir=cfg.data.path, split='val',  max_shift_x=cfg.training.max_shift_x, max_shift_y=cfg.training.max_shift_y, shared=shared_ct_dict) 
    train_dl = DataLoader(train_ds, batch_size=cfg.training.batch_size, num_workers=8, drop_last=True, pin_memory=True, persistent_workers=True)
    val_dl   = DataLoader(val_ds,   batch_size=cfg.training.batch_size, num_workers=4, drop_last=True, pin_memory=True, persistent_workers=True)

    # setup models
    cfm = cfg.model 
    patch_size = cfm.get('patch_size', cfm.get('patch_h', 16))
    dim = cfm.get('dim', cfm.get('embed_dim', 256))    
    if cfm.get('encoder', 'vit') == 'swin':
        from midi_rae.swin import SwinEncoder
        encoder = SwinEncoder(img_height=cfg.data.image_size, img_width=cfg.data.image_size, patch_h=cfm.patch_h, patch_w=cfm.patch_w,
                            embed_dim=cfm.embed_dim, depths=cfm.depths, num_heads=cfm.num_heads, window_size=cfm.window_size,
                            mlp_ratio=cfm.mlp_ratio, drop_path_rate=cfm.drop_path_rate).to(device)
        dims = tuple(cfm.embed_dim * 2**i for i in range(len(cfm.depths)-1, -1, -1))
        mae_decoder = SwinMAEDecoder(patch_size=patch_size, dims=dims).to(device)
    else:
        encoder = ViTEncoder(cfg.data.in_channels, (cfg.data.image_size, cfg.data.image_size), cfm.patch_size, 
                           cfm.dim, cfm.depth, cfm.heads).to(device)
        mae_decoder = LightweightMAEDecoder(patch_size=patch_size, dim=dim).to(device)

    if cfg.training.lambda_mae <=0: mae_decoder = None 
    cjprint("encoder, mae_decoder  =", encoder.__class__.__name__, mae_decoder.__class__.__name__,color="green")
    ema_encoder = EMAModel(encoder, eta=cfg.training.ema_eta, update_every=cfg.training.ema_update_every)
    params = list(encoder.parameters()) if mae_decoder is None else list(chain(encoder.parameters(), mae_decoder.parameters()))
    optimizer = torch.optim.AdamW(params, lr=cfg.training.lr)
    epoch_start = 1
    if (cfg.get('checkpoint', False)): # use "+checkpoint=<path>" from CLI
        ckpt_path =  cfg.get('checkpoint',None)
        encoder, ckpt = load_checkpoint(encoder, ckpt_path, return_all=True)
        #optimizer.load_state_dict(ckpt['optimizer_state_dict'])
        load_optimizer_state_partial(optimizer, ckpt['optimizer_state_dict'], device)
        epoch_start = ckpt['epoch'] + 1 # next epoch after the one completed in thecheckpoint
        try: mae_decoder = load_checkpoint(mae_decoder, ckpt_path.replace('enc_','maedec_'), return_all=False)
        except: pass

    if cfm.get('encoder', 'vit') == 'vit': 
        encoder = torch.compile(encoder, dynamic=True)
    elif False: #  swin compilation takes a while and is fraught with difficulty :-( 
        for i, stage in enumerate(encoder.stages):
            encoder.stages[i] = torch.compile(stage, mode="default")
    epoch_start = 1 # temp for now
    #scheduler = OneCycleLR(optimizer, max_lr=cfg.training.lr, steps_per_epoch=1, epochs=cfg.training.epochs, div_factor=5, 
    #                    **({'last_epoch': epoch_start-1} if epoch_start > 1 else {}))
    curr_learn = CurriculumSchedule(cfg)
    #scaler = torch.amp.GradScaler(device)
    
    if not(cfg.get('no_wandb', False)): 
        wandb.init(project=cfg.wandb.project, config=dict(cfg))
        wandb.define_metric("epoch")
        wandb.define_metric("*", step_metric="epoch")

    # Training loop
    global_step = (epoch_start - 1) * len(train_dl)
    viz_every = 5
    rprint("And this is training \n","yellow")
    for epoch in range(epoch_start, cfg.training.epochs+1):
        if wandb.run is not None: wandb.log({"epoch": epoch})
        encoder.train()
        train_loss = 0
        if cfg.training.get('init_shift_x',-1) > 0: 
            curr_learn.step(epoch, optimizer)
            shared_ct_dict['training'] = curr_learn(shared_ct_dict, epoch)
        for batch in tqdm(train_dl, desc=f"Epoch {epoch}/{cfg.training.epochs}"):
            global_step += 1
            optimizer.zero_grad(set_to_none=True)
            with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
                loss_dict, zs, enc_outs, recon_patches = compute_batch_loss(batch, encoder, cfg, global_step, mae_decoder=mae_decoder, ema_encoder=ema_encoder)
            #scaler.scale(loss_dict['loss']).backward()
            #scaler.step(optimizer)
            #scaler.update()
            loss_dict['loss'].backward()
            torch.nn.utils.clip_grad_norm_(params, max_norm=1.0)
            optimizer.step()
            if ema_encoder is not None: ema_encoder.update(encoder)
            train_loss += loss_dict['loss'].item()
            
        # At end of Epoch: validation, viz, etc
        encoder.eval()
        val_loss = 0
        with torch.no_grad():
            for batch in val_dl:
                with torch.autocast(device_type='cuda', dtype=torch.bfloat16):
                    val_loss_dict, zs, enc_outs, recon_patches = compute_batch_loss(batch, encoder, cfg, global_step, mae_decoder=mae_decoder, ema_encoder=ema_encoder)
                val_loss += val_loss_dict['loss'].item()

            train_loss /= len(train_dl)
            val_loss /= len(val_dl)
            print(f"Epoch {epoch}/{cfg.training.epochs}: train_loss={train_loss:.3f} val_loss={val_loss:.3f}")
            
            if wandb.run is not None: 
                wandb.log({ 
                    "train_loss":train_loss, "train_sim":loss_dict['sim'], "train_sigreg":loss_dict['sigreg'], "train_anchor":loss_dict.get('anchor',0), 
                    "train_mae": loss_dict.get('mae', 0),  "val_mae": val_loss_dict.get('mae', 0),
                    "val_loss":val_loss, "val_sim":val_loss_dict['sim'], "val_sigreg":val_loss_dict['sigreg'], "val_anchor":val_loss_dict.get('anchor',0),  
                    "max_shift_x":shared_ct_dict['training']['max_shift_x'], "max_shift_y":shared_ct_dict['training']['max_shift_y'],
                    "lr": optimizer.param_groups[0]['lr'], "epoch": epoch,
                    **{f"levels/train_{k}_L{l}": v for l, ld in enumerate(loss_dict.get('levels', [])) for k, v in ld.items()},
                    **{f"levels/val_{k}_L{l}": v for l, ld in enumerate(val_loss_dict.get('levels', [])) for k, v in ld.items()},
                })
                if epoch % viz_every == 0:  
                    rprint("But here's some numbers  ","yellow")
                    cjprint("Sending visualization data",color="green")
                    figs = make_emb_viz(enc_outs, epoch=epoch, encoder=encoder, batch=batch)
                    del figs
                    gc.collect()
                    
                if (mae_decoder is not None) and (epoch % (max(1,viz_every//5)) == 0):
                    viz_mae_recon(recon_patches, batch['img2'], enc_out=enc_outs[-1], epoch=epoch, patch_size=patch_size, return_maps=True)

        save_checkpoint((mae_decoder, encoder), epoch, val_loss, cfg, optimizer=optimizer, tag="") # optimzer gets saved with mae_decoder, not encoder

        #scheduler.step()

